changeSet.sql:
CREATE TABLE board (
    board_id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id VARCHAR(255) NOT NULL REFERENCES "user"(username),
    name VARCHAR(200) NOT NULL DEFAULT 'Board',
    manuscript_ids INTEGER[] NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ
);
CREATE INDEX idx_board_user ON board(user_id) WHERE deleted_at IS NULL;
ALTER TABLE daily_rule ADD COLUMN board_id INTEGER REFERENCES board(board_id) ON DELETE CASCADE;
CREATE INDEX idx_daily_rule_board ON daily_rule(board_id) WHERE board_id IS NOT NULL;
